namespace FileMapper.Semantics;

// Fixed source literals make replay independent of platform exp/log implementations. Tables were
// rounded once to 1e-6, with a 1/16 logit step; runtime interpolation and SGD use integer arithmetic.
internal static class PatternLearningMath
{
    internal const string Version = "projected-logistic-sgd-fixed/v1";
    internal const int Scale = 1000000;
    private static readonly int[] Sigmoid = [500000, 515620, 531209, 546738, 562177, 577495, 592667, 607663, 622459, 637031, 651355, 665411, 679179, 692642, 705785, 718594, 731059, 743168, 754915, 766294, 777300, 787931, 798187, 808067, 817574, 826712, 835484, 843895, 851953, 859664, 867036, 874077, 880797, 887205, 893309, 899121, 904651, 909907, 914901, 919643, 924142, 928409, 932453, 936285, 939913, 943348, 946597, 949669, 952574, 955319, 957912, 960361, 962673, 964855, 966914, 968856, 970688, 972415, 974043, 975577, 977023, 978385, 979668, 980876, 982014, 983085, 984094, 985043, 985936, 986777, 987568, 988313, 989013, 989672, 990292, 990874, 991423, 991938, 992423, 992879, 993307, 993710, 994089, 994445, 994780, 995095, 995390, 995668, 995930, 996176, 996406, 996623, 996827, 997019, 997199, 997368, 997527, 997677, 997817, 997949, 998073, 998190, 998299, 998402, 998499, 998590, 998675, 998755, 998830, 998901, 998968, 999030, 999089, 999144, 999196, 999245, 999290, 999333, 999374, 999412, 999447, 999481, 999512, 999542, 999569, 999596, 999620, 999643, 999665];
    private static readonly int[] Softplus = [693147, 724885, 757599, 791285, 825939, 861555, 898123, 935635, 974077, 1013437, 1053701, 1094851, 1136871, 1179742, 1223445, 1267958, 1313262, 1359333, 1406150, 1453690, 1501929, 1550845, 1600413, 1650610, 1701413, 1752799, 1804745, 1857227, 1910224, 1963714, 2017675, 2072087, 2126928, 2182180, 2237822, 2293837, 2350207, 2406913, 2463939, 2521270, 2578890, 2636783, 2694936, 2753335, 2811968, 2870820, 2929882, 2989141, 3048587, 3108210, 3167999, 3227946, 3288041, 3348277, 3408646, 3469139, 3529750, 3590473, 3651300, 3712226, 3773245, 3834352, 3895542, 3956809, 4018150, 4079560, 4141034, 4202570, 4264163, 4325811, 4387510, 4449256, 4511048, 4572882, 4634756, 4696668, 4758614, 4820595, 4882606, 4944647, 5006715, 5068810, 5130929, 5193070, 5255234, 5317417, 5379620, 5441841, 5504078, 5566332, 5628600, 5690882, 5753178, 5815485, 5877805, 5940135, 6002476, 6064826, 6127185, 6189553, 6251929, 6314312, 6376702, 6439099, 6501502, 6563911, 6626326, 6688746, 6751170, 6813599, 6876033, 6938470, 7000911, 7063356, 7125804, 7188256, 7250710, 7313167, 7375627, 7438089, 7500553, 7563019, 7625488, 7687958, 7750431, 7812905, 7875380, 7937857, 8000335];
    internal static string TableHash => CanonicalJson.Sha256(new { Version, Sigmoid, Softplus, StepQ = 62500 });
    internal static long Divide(long value, long denominator) => value < 0
        ? -((-value + denominator / 2) / denominator) : (value + denominator / 2) / denominator;
    internal static int Probability(int logitQ)
    {
        var p = Interpolate(Sigmoid, Math.Abs(logitQ));
        return logitQ < 0 ? Scale - p : p;
    }
    internal static int LogLoss(int logitQ, int label)
    {
        var absolute = Math.Abs(logitQ); var loss = Interpolate(Softplus, absolute);
        return (label == 1 && logitQ >= 0) || (label == 0 && logitQ < 0) ? loss - absolute : loss;
    }
    private static int Interpolate(int[] table, int absolute)
    {
        absolute = Math.Min(absolute, 8000000); var index = absolute / 62500; var remainder = absolute % 62500;
        return index == 128 ? table[128] : checked(table[index] + (int)Divide((long)(table[index + 1] - table[index]) * remainder, 62500));
    }
}
